INSERT INTO `official_letters` (`id`, `school_id`, `type`, `letter_category`, `reference_number`, `agenda_number`, `title`, `sender`, `recipient`, `letter_date`, `received_date`, `content`, `file_url`, `security_level`, `status`, `created_by`, `metadata_json`, `created_at`, `updated_at`) VALUES
(1, 3, 'INCOMING', 'UNDANGAN', '420/892/Disdik.OI/2026', 'AGD-2026-0001', 'Undangan Rapat Koordinasi Asesmen Nasional Berbasis Komputer (ANBK) 2026', 'Dinas Pendidikan & Kebudayaan Kab. Ogan Ilir', 'Kepala SMPIT Robbani Ogan Ilir', '2026-08-10 00:00:00', '2026-08-11 00:00:00', 'Sehubungan dengan persiapan pelaksanaan ANBK jenjang SMP tahun 2026, dimohon kehadiran Kepala Sekolah dan Proktor pada rapat koordinasi teknis.', NULL, 'SEGERA', 'DISPATCHED', 1, NULL, '2026-08-16 08:39:43', '2026-08-16 08:39:43'),
(2, 2, 'INCOMING', 'SURAT_EDARAN', 'B-342/Kk.06.04/PP.00/08/2026', 'AGD-2026-0002', 'Edaran Pelaksanaan Pekan Keterampilan & Seni Pendidikan Agama Islam (Pentas PAI)', 'Kementerian Agama Kab. Ogan Ilir', 'Kepala SDIT Robbani', '2026-08-12 00:00:00', '2026-08-13 00:00:00', 'Pemberitahuan petunjuk teknis lomba MHQ, Pidato PAI, dan Kaligrafi Islam tingkat Kabupaten.', NULL, 'BIASA', 'DISPATCHED', 1, NULL, '2026-08-16 08:39:43', '2026-08-16 08:39:43'),
(3, 3, 'OUTGOING', 'SURAT_EDARAN', '024/SMPIT-ROBBANI/SE/VIII/2026', NULL, 'Pemberitahuan Pelaksanaan Ujian Tengah Semester & Pembagian Rapor Siswa', 'SMPIT Robbani Ogan Ilir', 'Seluruh Orang Tua / Wali Santri SMPIT Robbani', '2026-08-15 00:00:00', NULL, 'Assalamu\'alaikum Warahmatullahi Wabarakatuh,\n\nDengan hormat, kami sampaikan bahwa pelaksanaan Asesmen Sumatif Tengah Semester (ASTS) Ganjil Tahun Ajaran 2026/2027 akan diselenggarakan pada tanggal 1 s/d 8 September 2026.\n\nDemikian pemberitahuan ini kami sampaikan, mohon bimbingan dan doa Bapak/Ibu di rumah.\n\nWassalamu\'alaikum Warahmatullahi Wabarakatuh.', NULL, 'BIASA', 'SIGNED', 1, NULL, '2026-08-16 08:39:43', '2026-08-16 08:39:43'),
(4, 4, 'OUTGOING', 'SURAT_TUGAS', '025/SMAIT-ROBBANI/ST/VIII/2026', NULL, 'Surat Tugas Pendampingan Lomba Olimpiade Sains Nasional (OSN) 2026', 'SMAIT Robbani Ogan Ilir', 'Ustadz Drs. Abdullah S.Pd', '2026-08-16 00:00:00', NULL, 'Yang bertanda tangan di bawah ini Kepala Sekolah SMAIT Robbani menugaskan kepada Guru Pembimbing untuk mendampingi kontingen siswa pada ajang OSN Tingkat Provinsi Sumatera Selatan.\n\nDemikian surat tugas ini dibuat untuk dilaksanakan dengan sebaik-baiknya.', NULL, 'SEGERA', 'SIGNED', 1, NULL, '2026-08-16 08:39:43', '2026-08-16 09:03:21'),
(5, 1, 'INCOMING', 'UNDANGAN', 'TEST/DISDIK/132', 'AGD-2026-0003', 'Uji Coba Surat Masuk ANBK 2026', 'Dinas Pendidikan Provinsi Sumsel', 'Kepala Sekolah / Yayasan Robbani', '2026-08-16 00:00:00', '2026-08-16 00:00:00', 'Undangan koordinasi teknis', NULL, 'SEGERA', 'DISPATCHED', 1, NULL, '2026-08-16 08:39:51', '2026-08-16 08:39:51'),
(6, 1, 'OUTGOING', 'SURAT_EDARAN', '003/TKIT/SE/VIII/2026', NULL, 'Surat Edaran Uji Coba KBM Semester Ganjil', 'KB / TKIT Robbani', 'Seluruh Wali Santri SIT Robbani', '2026-08-16 00:00:00', NULL, 'Pemberitahuan resmi KBM semester baru.', NULL, 'BIASA', 'SIGNED', 1, NULL, '2026-08-16 08:39:51', '2026-08-16 08:39:51'),
(7, 1, 'OUTGOING', 'SURAT_TUGAS', '099/TEST/ST/2026', NULL, 'Surat Tugas Bulk Signing Demo', NULL, 'Dewan Guru', '2026-08-16 00:00:00', NULL, 'Tugas dinas', NULL, 'BIASA', 'SIGNED', NULL, NULL, '2026-08-16 08:39:51', '2026-08-16 08:39:51'),
(8, NULL, 'OUTGOING', 'SURAT_EDARAN', '005/YAYASAN-ROBBANI/SE/VIII/2026', NULL, 'Libur Hari Kemerdekaan', 'Yayasan Generasi Robbani', 'Seluruh SDM SIT Robbani', '2026-08-16 00:00:00', NULL, 'Assalamu\'alaikum Warahmatullahi Wabarakatuh,\r\n\r\nSehubungan dengan peringatan Hari Kemerdekaan RI, kami memberitahukan kepada seluruh SDM SIT Robbani bahwa kegiatan belajar mengajar (KBM) akan diliburkan mulai tanggal 1 s/d 5 Ramadhan.\r\n\r\nDemikian surat edaran ini kami sampaikan, atas perhatian dan kerjasama Bapak/Ibu kami ucapkan terima kasih.\r\n\r\nWassalamu\'alaikum Warahmatullahi Wabarakatuh.', NULL, 'SEGERA', 'SIGNED', 1, NULL, '2026-08-16 08:47:23', '2026-08-16 08:59:51'),
(9, 1, 'INCOMING', 'UNDANGAN', 'TEST/DISDIK/857', 'AGD-2026-0004', 'Uji Coba Surat Masuk ANBK 2026', 'Dinas Pendidikan Provinsi Sumsel', 'Kepala Sekolah / Yayasan Robbani', '2026-08-16 00:00:00', '2026-08-16 00:00:00', 'Undangan koordinasi teknis', NULL, 'SEGERA', 'DISPATCHED', 1, NULL, '2026-08-16 08:55:30', '2026-08-16 08:55:30'),
