('contact_email', 'info@sitrobbani.sch.id', '2026-08-14 12:03:23', '2026-08-15 14:42:10'),
('contact_address', 'Indralaya, Kabupaten Ogan Ilir, Sumatera Selatan', '2026-08-14 12:03:23', '2026-08-14 12:03:23'),
('bpi_badge', 'Bina Pribadi Islami & Character Building', '2026-08-14 12:03:23', '2026-08-14 12:03:23'),
('bpi_title', 'Mutabaah Yaumiyah, Al-Qur\'an & Pembentukan Karakter', '2026-08-14 12:03:23', '2026-08-14 12:03:23'),
('bpi_desc', 'Program unggulan pembentukan karakter siswa Rabbani melalui Ibadah Yaumiyah, Tahfidz Al-Qur\'an, Bina Pribadi Islami (BPI), dan budaya ramah anak di Ogan Ilir.', '2026-08-14 12:03:23', '2026-08-14 12:03:23'),
('website_theme', 'theme-magenta', '2026-08-14 12:32:30', '2026-08-14 17:36:24'),
('school_hero_badge', '✨ YAYASAN PENDIDIKAN ISLAM TERPADU ROBBANI', '2026-08-14 12:32:30', '2026-08-14 12:32:30'),
('school_hero_title', 'Pendidikan Karakter Islami & Keunggulan Akademik Digital', '2026-08-14 12:32:30', '2026-08-14 12:32:30'),
('school_hero_desc', 'Sekolah Islam Terpadu Robbani menyelenggarakan pendidikan terpadu dari jenjang TK, SD, SMP hingga SMA dengan Kurikulum Merdeka, Kekhasan JSIT, Pembiasaan Al-Qur\'an (Tahfidz), Mutaba\'ah BPI, dan Platform Digital SmartEdu.', '2026-08-14 12:32:30', '2026-08-14 12:32:30'),
('hero_bg_file', NULL, '2026-08-14 16:23:21', '2026-08-14 16:23:21'),
('hero_bg_image', '/uploads/cms/hero_bg_6a7f4563c3595_1786725731.webp?v=1786725731', '2026-08-14 16:23:21', '2026-08-14 16:42:11'),
