INSERT INTO `site_settings` (`key`, `value`, `created_at`, `updated_at`) VALUES
('system_traffic_mode', 'NORMAL', '2026-08-15 14:31:09', '2026-08-15 14:31:29'),
('unit_profile_sdit', '{\n    "name": "SDIT Robbani Ogan Ilir",\n    "code": "SDIT",\n    "npsn": "69985678",\n    "akreditasi": "Terakreditasi B",\n    "tagline": "Mencetak Generasi Qur\'ani, Berkarakter Karimah, & Cerdas Sains",\n    "principal_name": "Nur Amalia, S.Pd",\n    "principal_title": "Kepala Sekolah SDIT Robbani Ogan Ilir",\n    "principal_photo": "/uploads/wp_assets/99acbccf4209ca4a2b23e2b9a53f2b4e.webp",\n    "principal_greeting": "Assalamu\'alaikum Warahmatullahi Wabarakatuh. Selamat datang di SDIT Robbani. Kami berkomitmen memberikan pendidikan dasar terbaik yang menyeimbangkan antara capaian hafalan Al-Qur\'an, akademik sains unggulan, serta kepemimpinan berakhlak mulia.",\n    "description": "Sekolah Dasar Islam Terpadu berakreditasi B di Ogan Ilir. Memadukan Kurikulum Merdeka Nasional dengan Kekhasan JSIT (Jaringan Sekolah Islam Terpadu), Tahfidz Al-Qur\'an 3-5 Juz Mutqin, Sains Olimpic Club, Koding Digital, & Pembentukan Karakter Islam.",\n    "vision": "Menjadi Sekolah Dasar Islam Terpadu Model dalam Mencetak Generasi Qur\'ani, Cerdas Berakhlak, dan Berprestasi Nasional.",\n    "missions": [\n        "Menyelenggarakan bimbingan Al-Qur\'an dengan target kelulusan minimal 3-5 Juz secara mutqin.",\n        "Menerapkan Kurikulum Merdeka terintegrasi nilai-nilai keislaman dan pembiasaan ibadah harian.",\n        "Mengembangkan minat bakat siswa dalam bidang sains, koding digital, seni, dan kepanduan.",\n        "Membentuk karakter kepemimpinan islami melalui pembinaan Bina Pribadi Islam (BPI)."\n    ],\n    "phone": "0811747472",\n    "students_count": 450,\n    "employees_count": 38,\n    "classrooms_count": 18,\n    "target_hafalan": "3 - 5 Juz Mutqin",\n    "programs": [\n        {\n            "title": "Tahfidz Al-Qur\'an 3-5 Juz",\n            "icon": "\\ud83d\\udcd6",\n            "desc": "Bimbingan tasmi\', murojaah harian, dan wisuda tahfidz tahunan bersama hafidz tersertifikasi."\n        },\n        {\n            "title": "Bina Pribadi Islam (BPI)",\n            "icon": "\\ud83c\\udf1f",\n            "desc": "Mentoring kelompok kecil untuk penanaman aqidah, karakter, dan kepemimpinan islami."\n        },\n        {\n            "title": "Koding & Science Club",\n            "icon": "\\ud83d\\udcbb",\n            "desc": "Pembelajaran dasar pemograman, robotik sederhana, dan eksperimen sains sekolah."\n        },\n        {\n            "title": "Pramuka SIT & Archery",\n            "icon": "\\ud83c\\udff9",\n            "desc": "Kegiatan kepanduan khas JSIT, panahan sunnah, serta ketangkasan fisik outdoor."\n        }\n    ],\n    "facilities": [\n        {\n            "title": "Kolam Renang Sekolah",\n            "badge": "Fasilitas Unggulan SDIT",\n            "icon": "\\ud83c\\udfca\\u200d\\u2642\\ufe0f",\n            "desc": "SD Islam Terpadu Robbani memiliki kolam renang sendiri di sekolah dan memiliki ekskul renang yang rutin dilaksanakan.",\n            "image": "/uploads/wp_assets/4afcf92f02340d52d956cd13a2ee9e84.webp"\n        },\n        {\n            "title": "Ruang Kelas Ber-AC",\n            "badge": "Ruang Belajar",\n            "icon": "\\u2744\\ufe0f",\n            "desc": "SD Islam Terpadu Robbani memiliki ruang kelas yang semuanya didesain senyaman mungkin melalui penyediaan fasilitas AC dan penerangan.",\n            "image": "/uploads/wp_assets/a2b54fd4d82d35aa950b4f75499b38f7.webp"\n        },\n        {\n            "title": "Mushola atau Saung",\n            "badge": "Sarana Ibadah",\n            "icon": "\\ud83d\\udd4c",\n            "desc": "SD Islam Terpadu Robbani memiliki mushola atau saung yang didesain unik sehingga siswa terasa nyaman ketika beribadah.",\n            "image": "/uploads/wp_assets/f3942ec870a00c294dde1f7ee4003536.webp"\n        },\n        {\n            "title": "Aula Sekolah",\n            "badge": "Gedung Pertemuan",\n            "icon": "\\ud83c\\udfdb\\ufe0f",\n            "desc": "SD Islam Terpadu Robbani memiliki ruangan aula yang biasanya digunakan untuk event, seminar, atau kegiatan upacara sekolah.",\n            "image": "/uploads/wp_assets/f5e59e9ae69a00854a6913c4cbc130c6.webp"\n        },\n        {\n            "title": "Lapangan Olahraga",\n            "badge": "Area Ketangkasan",\n            "icon": "\\u26bd",\n            "desc": "SD Islam Terpadu Robbani mempunyai lapangan olahraga di ruang terbuka sebagai pelataran aktivitas fisik siswa.",\n            "image": "/uploads/wp_assets/531016d4e4a882033285f5790bce2064.webp"\n        }\n    ],\n    "ekskul": [\n        {\n            "title": "Ekskul Renang",\n            "badge": "Olahraga Air",\n            "icon": "\\ud83c\\udfca\\u200d\\u2642\\ufe0f",\n            "desc": "Ekskul renang rutin di kolam renang milik sekolah untuk melatih fisik, keberanian, dan kesehatan siswa.",\n            "image": "/uploads/wp_assets/4afcf92f02340d52d956cd13a2ee9e84.webp"\n        },\n        {\n            "title": "Life Skill: Mewarnai & Seni",\n            "badge": "Seni & Kreativitas",\n            "icon": "\\ud83c\\udfa8",\n            "desc": "Wadah eksplorasi keindahan warna, seni lukis, dan imajinasi visual anak.",\n            "image": "/uploads/wp_assets/ea0660183131e385e4496261b685e658.webp"\n        },\n        {\n            "title": "Pramuka SIT",\n            "badge": "Kepanduan Wajib",\n            "icon": "\\ud83c\\udfd5\\ufe0f",\n            "desc": "Pelatihan karakter kepemimpinan, kepanduan khas JSIT, kedermawanan, dan kerja sama regu.",\n            "image": "/uploads/wp_assets/615a5e20e8d37cd82f72a1979293a4c7.webp"\n        },\n        {\n            "title": "Bina Pribadi Islam (BPI)",\n            "badge": "Mentoring Karakter",\n            "icon": "\\ud83c\\udf1f",\n            "desc": "Pembinaan akhlak karimah, adab harian, aqidah lurus, dan sholat berjamaah.",\n            "image": "/uploads/wp_assets/c87bfc14b6ce3ea38a77be262f2ce7f3.webp"\n        },\n        {\n            "title": "Ekskul Tari Seni Tradisional",\n            "badge": "Seni Budaya",\n            "icon": "\\ud83d\\udc83",\n            "desc": "Pelatihan seni tari kreasi islami dan budaya nusantara untuk pentas sekolah.",\n            "image": "/uploads/wp_assets/7264e64c39a391aae44f3938d9139251.webp"\n        },\n        {\n            "title": "Ekskul Memanah (Archery)",\n            "badge": "Olahraga Sunnah",\n            "icon": "\\ud83c\\udff9",\n            "desc": "Melatih fokus, konsentrasi, ketenangan emosi, dan kedisiplinan diri siswa.",\n            "image": "/uploads/wp_assets/f2f96d505486e0f1fcc472ea38fa070b.webp"\n        },\n        {\n            "title": "Ekskul Coding Digital",\n            "badge": "Teknologi & IT",\n            "icon": "\\ud83d\\udcbb",\n            "desc": "Pembelajaran logika pemograman dasar dan logika komputasi anak.",\n            "image": "/uploads/wp_assets/a4ca1fc6aecb7d847f81c1fe39850c28.webp"\n        },\n        {\n            "title": "Ekskul Futsal",\n            "badge": "Olahraga Tim",\n            "icon": "\\u26bd",\n            "desc": "Pengembangan bakat sepak bola/futsal, kekompakan tim, dan ketangkasan olahraga.",\n            "image": "/uploads/wp_assets/0943e8c34f1c0d4053fddb3daec16701.webp"\n        },\n        {\n            "title": "English Club",\n            "badge": "Bahasa Asing",\n            "icon": "\\ud83d\\udde3\\ufe0f",\n            "desc": "Pembiasaan percakapan Bahasa Inggris sehari-hari secara menyenangkan.",\n            "image": "/uploads/wp_assets/c36ae01f6fd03a8ab1ceaa5bd5a00365.webp"\n        },\n        {\n            "title": "Life Skill: Bulu Tangkis",\n            "badge": "Olahraga Kebugaran",\n            "icon": "\\ud83c\\udff8",\n            "desc": "Latihan ketangkasan refleksi, kelincahan, dan kebugaran jasmani.",\n            "image": "/uploads/wp_assets/b1da73a0eab0a7f649e6bc90138ae5bf.webp"\n        },\n        {\n            "title": "Life Skill: Tahfidz Intensive",\n            "badge": "Al-Qur\'an",\n            "icon": "\\ud83d\\udcd6",\n            "desc": "Halaqoh pendalaman hafalan Al-Qur\'an dengan metode talaqqi.",\n            "image": "/uploads/wp_assets/7fdd1bf334b38771207f1eab34b2ee32.webp"\n        }\n    ],\n    "teachers": [\n        {\n            "name": "Sholahuddin Gultom",\n            "role": "Guru Kelas",\n            "photo": "/uploads/wp_assets/b287c1f165cafe88c54bd2ec9bc6c0cd.webp"\n        },\n        {\n            "name": "Rini Nur Aisah, S.Pd",\n            "role": "Guru Kelas",\n            "photo": "/uploads/wp_assets/62500a42dce9094e4f0a7accd68910ef.webp"\n        },\n        {\n            "name": "Erina, S.Pd",\n            "role": "Guru Kelas",\n            "photo": "/uploads/wp_assets/cb2206e48bb0edc5b5e0a40384358aaf.webp"\n        },\n        {\n            "name": "Nur Amalia, S.Pd",\n            "role": "Kepala Sekolah",\n            "photo": "/uploads/wp_assets/99acbccf4209ca4a2b23e2b9a53f2b4e.webp"\n        },\n        {\n            "name": "Verda Novita Sari, S.Pd",\n            "role": "Guru Kelas",\n            "photo": "/uploads/wp_assets/ad452dad9895890a6e5fd20c0e57e891.webp"\n        },\n        {\n            "name": "Ranti Saputri, S.TP",\n            "role": "Guru Kelas",\n            "photo": "/uploads/wp_assets/5199b18b81aa79a2d1ac2938b3b74474.webp"\n        },\n        {\n            "name": "Veti Susanti, S.Pd",\n            "role": "Guru Kelas",\n            "photo": "/uploads/wp_assets/59757bcc8773617abf01370f063693e3.webp"\n        },\n        {\n            "name": "Marisa, S.Pd",\n            "role": "Guru Kelas",\n            "photo": "/uploads/wp_assets/130e5322d5638b046f0f39dedefb5135.webp"\n        },\n        {\n            "name": "Atainah Ul Hukma, S.Si",\n            "role": "Guru Kelas",\n            "photo": "/uploads/wp_assets/1710e9009670596fd55d27b0961c70c6.webp"\n        },\n        {\n            "name": "Anisa, S.Pd",\n            "role": "Guru Kelas",\n            "photo": "/uploads/wp_assets/c33d9a961dcc730923dc3e1eebb